async function warning(title, message, id) {
      let viewed = await cookieStore.get(`viewed_${id}`).then((c) => c ? c.value : "false");
      if(viewed === "true") {
            return;
      }

      const msg_element = document.createElement("span");
      msg_element.innerText = message;
      MSPFA.dialog(title, msg_element, ["Okay"]);
      await cookieStore.set({
            name: `viewed_${id}`, 
            value: true,
            maxAge: 24 * 60 * 60 * 365
      });
}

warning("Warning", "This comic is a work of fiction. It depicts and discusses sensitive and suggestive topics, and the content in it is not inherently indicative of the author's beliefs. Think of it as MPAA R rated. Viewer Discretion is advised!", 1);

